\documentclass[10pt]{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=18mm]{geometry}
\usepackage{graphicx}
\usepackage{xcolor}
\usepackage{tcolorbox}
\usepackage{tikz}
\usepackage{enumitem}
\usepackage{type1cm}
\usepackage{hyperref}
\hypersetup{hidelinks}

% --- Palette (cool clinical) ---
\definecolor{primary}{HTML}{0B1F3A}   % deep navy
\definecolor{secondary}{HTML}{1B4B66} % steel blue
\definecolor{accent}{HTML}{1F8A8A}    % muted teal
\definecolor{bg}{HTML}{F7FAFC}        % near-white
\definecolor{textgray}{HTML}{1F2937}
\definecolor{muted}{HTML}{4B5563}
\definecolor{risk}{HTML}{D97706}      % amber (sparingly)
\definecolor{riskbg}{HTML}{FFF7ED}
\definecolor{tealbg}{HTML}{EEF8F8}
\definecolor{bluebg}{HTML}{EEF4FA}
\definecolor{navybg}{HTML}{F1F5F9}

\pagecolor{bg}
\pagestyle{empty}
\setlength{\parindent}{0pt}
\setlist[itemize]{leftmargin=*, itemsep=4pt, topsep=2pt}

% --- Figure macro ---
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{28}{34}\selectfont\color{muted}\textit{#3}}\vspace{2mm}%
}

% --- Card system (left accent stripe) ---
\tcbset{
  posterbox/.style={
    enhanced,
    arc=0pt,
    boxrule=0pt,
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt,
    valign=top,
    drop shadow={opacity=0.16},
  },
  bluecard/.style={
    posterbox,
    colback=bluebg,
    colbacktitle=bluebg,
    coltitle=secondary,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    titlerule style={secondary!50},
    borderline west={6pt}{0pt}{secondary},
  },
  tealcard/.style={
    posterbox,
    colback=tealbg,
    colbacktitle=tealbg,
    coltitle=accent,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent},
    titlerule style={accent!50},
    borderline west={6pt}{0pt}{accent},
  },
  navycard/.style={
    posterbox,
    colback=navybg,
    colbacktitle=navybg,
    coltitle=primary,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{primary},
    titlerule style={primary!50},
    borderline west={6pt}{0pt}{primary},
  },
  riskcard/.style={
    posterbox,
    colback=riskbg,
    colbacktitle=riskbg,
    coltitle=risk,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{risk},
    titlerule style={risk!55},
    borderline west={7pt}{0pt}{risk},
  },
  takeaway/.style={
    enhanced,
    arc=0pt,
    boxrule=0pt,
    colback=primary,
    colbacktitle=primary,
    coltitle=white,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{white},
    left=18pt, right=16pt, top=10pt, bottom=10pt,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    borderline west={7pt}{0pt}{accent},
    drop shadow={opacity=0.18},
  }
}

% --- Headline metric card ---
\newcommand{\metric}[4]{%
\begin{tcolorbox}[enhanced, arc=0pt, boxrule=0pt,
  colback=white, drop shadow={opacity=0.12},
  borderline west={6pt}{0pt}{#1},
  left=14pt, right=12pt, top=10pt, bottom=10pt]
  {\fontsize{72}{86}\selectfont\bfseries\color{#1} #2}\\[2mm]
  {\fontsize{30}{36}\selectfont\bfseries\color{textgray} #3}\\[1mm]
  {\fontsize{26}{32}\selectfont\color{muted} #4}
\end{tcolorbox}%
}

% --- Grid helpers (manual positioning with minipages) ---
\newcommand{\colw}{0.318\textwidth} % 3 columns with gutters
\newcommand{\gutter}{0.018\textwidth}

\begin{document}

% ===== Title bar =====
\begin{tcolorbox}[enhanced, arc=0pt, boxrule=0pt,
  colback=primary, left=18pt, right=18pt, top=14pt, bottom=14pt]
  {\fontsize{90}{108}\selectfont\bfseries\color{white} Large Language Models in Medicine: Opportunities, Risks, and the Path Forward}\\[6mm]
  {\fontsize{42}{50}\selectfont\color{white} Medical AI \& Digital Health Conference 2024 \hfill \color{accent}\rule{20mm}{3mm}\,\color{white} Data-forward review poster}
\end{tcolorbox}

\vspace{8mm}

% ===== Headline metrics (visual anchors) =====
\noindent
\begin{minipage}[t]{\colw}
  \metric{secondary}{>90\%}{GPT-4 USMLE Score}{Exceeded passing threshold across all three USMLE steps}
\end{minipage}\hspace{\gutter}
\begin{minipage}[t]{\colw}
  \metric{accent}{500+}{PubMed Articles (2023)}{Peer-reviewed publications on LLMs in medicine in 2023}
\end{minipage}\hspace{\gutter}
\begin{minipage}[t]{\colw}
  \metric{risk}{Up to 30\%}{Hallucination Rate}{Fabricated references or inaccurate clinical information in some studies}
\end{minipage}

\vspace{6mm}

\noindent
\begin{minipage}[t]{\colw}
  \metric{secondary}{\$10.5B}{Global Health LLM Market (2030)}{Projected market size for healthcare LLM solutions}
\end{minipage}\hspace{\gutter}
\begin{minipage}[t]{\colw}
\begin{tcolorbox}[navycard, title={Key Message}]
  {\fontsize{34}{44}\selectfont\color{textgray}
  LLMs show remarkable capability in medical contexts, but the gap between benchmark performance and safe clinical deployment is substantial. Responsible adoption requires structured evaluation, governance, and human oversight.
  }
\end{tcolorbox}
\end{minipage}\hspace{\gutter}
\begin{minipage}[t]{\colw}
\begin{tcolorbox}[riskcard, title={Tension To Resolve}]
  {\fontsize{34}{44}\selectfont\color{textgray}
  High exam scores \textbf{do not} imply reliable bedside performance. Hallucinations, bias, privacy risk, and weak clinical validation remain key barriers.
  }
\end{tcolorbox}
\end{minipage}

\vspace{8mm}

% ===== Main body (3-column layout) =====
\noindent
\begin{minipage}[t]{\colw}
  \begin{tcolorbox}[navycard, title={What Are LLMs and Why Do They Matter?}]
    {\fontsize{34}{44}\selectfont\color{textgray}
    \begin{itemize}
      \item Foundation models trained on massive text corpora
      \item Strong medical text understanding \& generation
      \item Rapid adoption across health systems (early)
    \end{itemize}
    \vspace{2mm}
    \colorbox{secondary!20}{\parbox{0.95\linewidth}{\fontsize{32}{40}\selectfont\bfseries\color{textgray} Why now: \;Scale + instruction tuning \;$\Rightarrow$\; usable clinical assistants}}
    }
  \end{tcolorbox}

  \vspace{8mm}

  \begin{tcolorbox}[tealcard, title={Key Clinical \& Research Applications}]
    {\fontsize{34}{44}\selectfont\color{textgray}
    \begin{itemize}
      \item Clinical documentation: notes, summaries
      \item Patient communication: jargon simplification
      \item Education: tutoring, exam preparation
      \item Research: literature synthesis, drafting
      \item Decision support: differential suggestions (research)
    \end{itemize}
    \vspace{2mm}
    \colorbox{accent!20}{\parbox{0.95\linewidth}{\fontsize{32}{40}\selectfont\bfseries\color{textgray} Fastest adoption: documentation \& patient messaging}}}
  \end{tcolorbox}

  \vspace{8mm}

  \begin{tcolorbox}[bluecard, title={Performance Benchmarks \& Evidence}]
    {\fontsize{34}{44}\selectfont\color{textgray}
    \begin{itemize}
      \item GPT-4: \textbf{>90\%} across USMLE steps
      \item Med-PaLM 2: \textbf{86.5\%} on MedQA
      \item Prior models: near passing threshold
    \end{itemize}
    \vspace{2mm}
    \colorbox{secondary!20}{\parbox{0.95\linewidth}{\fontsize{32}{40}\selectfont\bfseries\color{textgray} Evidence gap: benchmarks \;$\neq$\; prospective clinical trials}}}
  \end{tcolorbox}
\end{minipage}\hspace{\gutter}
\begin{minipage}[t]{\colw}
  \begin{tcolorbox}[riskcard, title={Risks, Limitations \& Ethical Concerns}]
    {\fontsize{34}{44}\selectfont\color{textgray}
    \begin{itemize}
      \item \textbf{Hallucinations}: plausible but incorrect outputs
      \item \textbf{Bias \& equity}: disparate recommendations
      \item \textbf{Privacy}: PHI exposure, compliance risk
      \item \textbf{Validation}: few prospective studies
      \item \textbf{Automation bias}: over-reliance by clinicians
    \end{itemize}
    \vspace{2mm}
    \colorbox{risk!22}{\parbox{0.95\linewidth}{\fontsize{32}{40}\selectfont\bfseries\color{textgray} Failure mode: confident errors \;$\to$\; patient harm}}}
  \end{tcolorbox}

  \vspace{8mm}

  \begin{tcolorbox}[navycard, title={What “Good” Looks Like}]
    {\fontsize{34}{44}\selectfont\color{textgray}
    \begin{itemize}
      \item High-stakes tasks require verification pathways
      \item Calibrated uncertainty \& retrieval-grounding
      \item Auditable logs, monitoring, incident response
    \end{itemize}
    \vspace{2mm}
    \colorbox{accent!18}{\parbox{0.95\linewidth}{\fontsize{32}{40}\selectfont\bfseries\color{textgray} Design for oversight, not autonomy}}}
  \end{tcolorbox}

  \vspace{8mm}

  \begin{tcolorbox}[bluecard, title={Clinical Deployment Reality Check}]
    {\fontsize{34}{44}\selectfont\color{textgray}
    \begin{itemize}
      \item Real-world inputs are messy \& incomplete
      \item Distribution shift across sites \& populations
      \item Liability and workflow integration dominate
    \end{itemize}
    \vspace{2mm}
    \colorbox{secondary!18}{\parbox{0.95\linewidth}{\fontsize{32}{40}\selectfont\bfseries\color{textgray} “Works on exams” \;$\not\Rightarrow$\; safe in care}}}
  \end{tcolorbox}
\end{minipage}\hspace{\gutter}
\begin{minipage}[t]{\colw}
  \begin{tcolorbox}[takeaway, title={Framework for Responsible Deployment (Actionable)}]
    {\fontsize{34}{44}\selectfont\color{white}
    \begin{enumerate}[leftmargin=*, itemsep=6pt, topsep=2pt]
      \item \textbf{Prospective evaluation}: diverse sites \& populations
      \item \textbf{Human-in-the-loop}: clinician oversight of outputs
      \item \textbf{Transparency}: limitations, data sources, failure modes
      \item \textbf{Equity audits}: subgroup performance \& harms
      \item \textbf{Governance}: monitoring, reporting, model updates
      \item \textbf{Regulatory alignment}: FDA/EMA/WHO pathways
    \end{enumerate}
    \vspace{2mm}
    \colorbox{accent!35}{\parbox{0.95\linewidth}{\fontsize{32}{40}\selectfont\bfseries\color{primary} Bottom line: evidence + oversight + governance}}}
  \end{tcolorbox}

  \vspace{8mm}

  \begin{tcolorbox}[navycard, title={References (Selected)}]
    {\fontsize{30}{40}\selectfont\color{textgray}
    \begin{itemize}
      \item Nature Medicine (Jul 2023): LLMs in healthcare review
      \item USMLE-style evaluations of GPT-4 medical reasoning
      \item MedQA benchmarks for Med-PaLM 2 (86.5\%)
      \item Studies of hallucinated citations in medical QA
    \end{itemize}
    }
  \end{tcolorbox}

  \vspace{8mm}

  \begin{tcolorbox}[tealcard, title={Contact \& Reproducibility}]
    {\fontsize{30}{40}\selectfont\color{textgray}
    \begin{itemize}
      \item Poster generated from provided brief + specs
      \item Add QR: project page / dataset / code (placeholder)
    \end{itemize}
    }
  \end{tcolorbox}
\end{minipage}

\end{document}
